const createTreeClass=(keyName="id",parentKeyName="parentId",childrenKey="children")=>{const TreeClass={keyName,parentKeyName,childrenKey,findRoots:allNodes=>{var results=[];for(let i=0;i<allNodes.length;i++){var isRoot=!0;for(let k=0;k<allNodes.length;k++)if(allNodes[i][TreeClass.parentKeyName]===allNodes[k][TreeClass.keyName]){isRoot=!1;break}if(isRoot){const nodeInfo=Object.assign({},allNodes[i]);results.push(nodeInfo)}}return results},findChildren:(root,allNodes)=>{var children=[];for(let i=0;i<allNodes.length;i++)if(allNodes[i][TreeClass.parentKeyName]===root[TreeClass.keyName]){const nodeInfo=Object.assign({},allNodes[i]);children.push(nodeInfo)}for(let i=0;i<children.length;i++){var tmpChildren=TreeClass.findChildren(children[i],allNodes);tmpChildren.length>0&&(children[i][TreeClass.childrenKey]=tmpChildren)}return children.length>0&&(root[TreeClass.childrenKey]=children),children},resetBottom:allNodes=>{var results=[];for(let i=0;i<allNodes.length;i++){var hasChild=!1;for(let k=0;k<allNodes.length;k++)if(allNodes[i][TreeClass.keyName]===allNodes[k][TreeClass.parentKeyName]){hasChild=!0;break}hasChild&&results.push(allNodes[i])}return results},buildTree:dataList=>{if(!dataList||dataList.length<=1)return dataList;for(var roots=TreeClass.findRoots(dataList),i=0;i<roots.length;i++)TreeClass.findChildren(roots[i],dataList);return roots},getTreeNodeProp:(treeList,prop)=>{if(treeList.length>0&&prop!==""){const propArr=[];return treeList.map(item=>{if(item.children){const childrenProps=TreeClass.getTreeNodeProp(item.children,prop);propArr.push(...childrenProps)}propArr.push(item[prop])}),propArr}},clearChecked:treeList=>{if(!(treeList.length<=0))return treeList.map(item=>{treeList.checked=!1,item.children&&(item.children=TreeClass.clearChecked(item.children))}),treeList}};return TreeClass};export{createTreeClass as c};
